import React, { useContext } from 'react';
import { ThemeContext } from '../context/ThemeContext';
import './ColorPaletteSelector.css';

interface ColorPalette {
  id: string;
  name: string;
  type: 'warm' | 'classic';
  colors: {
    bgPrimary: string;
    bgSecondary: string;
    bgTertiary: string;
    textPrimary: string;
    textSecondary: string;
    textMuted: string;
    accentPrimary: string;
    accentSecondary: string;
    borderColor: string;
    shadowColor: string;
    navBg: string;
    cardBg: string;
  };
}

const ColorPaletteSelector: React.FC = () => {
  const themeContext = useContext(ThemeContext);

  // Early return if context is not available
  if (!themeContext) {
    return null;
  }

  const { setCustomPalette, customColors } = themeContext;

  const warmPalettes: ColorPalette[] = [
    {
      id: 'warm-orange',
      name: 'Naranja Potente',
      type: 'warm',
      colors: {
        bgPrimary: '#ff6b35',
        bgSecondary: '#ff8c42',
        bgTertiary: '#ffa726',
        textPrimary: '#ffffff',
        textSecondary: '#fff3e0',
        textMuted: '#ffe0b2',
        accentPrimary: '#ff5722',
        accentSecondary: '#ff7043',
        borderColor: '#e65100',
        shadowColor: 'rgba(255, 107, 53, 0.3)',
        navBg: 'rgba(255, 107, 53, 0.95)',
        cardBg: 'rgba(255, 140, 66, 0.9)'
      }
    },
    {
      id: 'warm-yellow',
      name: 'Amarillo Dorado',
      type: 'warm',
      colors: {
        bgPrimary: '#ffc107',
        bgSecondary: '#ffd54f',
        bgTertiary: '#ffe082',
        textPrimary: '#000000',
        textSecondary: '#212121',
        textMuted: '#424242',
        accentPrimary: '#ff9800',
        accentSecondary: '#ffb74d',
        borderColor: '#f57f17',
        shadowColor: 'rgba(255, 193, 7, 0.3)',
        navBg: 'rgba(255, 193, 7, 0.95)',
        cardBg: 'rgba(255, 213, 79, 0.9)'
      }
    },
    {
      id: 'warm-garnet',
      name: 'Granate Elegante',
      type: 'warm',
      colors: {
        bgPrimary: '#8d1b3d',
        bgSecondary: '#a52a2a',
        bgTertiary: '#c62828',
        textPrimary: '#ffffff',
        textSecondary: '#ffebee',
        textMuted: '#ffcdd2',
        accentPrimary: '#d32f2f',
        accentSecondary: '#ef5350',
        borderColor: '#6a1b9a',
        shadowColor: 'rgba(141, 27, 61, 0.3)',
        navBg: 'rgba(141, 27, 61, 0.95)',
        cardBg: 'rgba(165, 42, 42, 0.9)'
      }
    },
    {
      id: 'classic-black',
      name: 'Negro Clásico',
      type: 'classic',
      colors: {
        bgPrimary: '#000000',
        bgSecondary: '#111111',
        bgTertiary: '#1a1a1a',
        textPrimary: '#ffffff',
        textSecondary: '#e0e0e0',
        textMuted: '#a0a0a0',
        accentPrimary: '#ff6b35',
        accentSecondary: '#ff8c42',
        borderColor: '#333333',
        shadowColor: 'rgba(255, 107, 53, 0.2)',
        navBg: 'rgba(0, 0, 0, 0.95)',
        cardBg: 'rgba(17, 17, 17, 0.9)'
      }
    },
    {
      id: 'warm-terracotta',
      name: 'Terracota Cálido',
      type: 'warm',
      colors: {
        bgPrimary: '#d84315',
        bgSecondary: '#e64a19',
        bgTertiary: '#f4511e',
        textPrimary: '#ffffff',
        textSecondary: '#fff3e0',
        textMuted: '#ffe0b2',
        accentPrimary: '#ff5722',
        accentSecondary: '#ff7043',
        borderColor: '#bf360c',
        shadowColor: 'rgba(216, 67, 21, 0.3)',
        navBg: 'rgba(216, 67, 21, 0.95)',
        cardBg: 'rgba(230, 74, 25, 0.9)'
      }
    },
    {
      id: 'warm-amber',
      name: 'Ámbar Intenso',
      type: 'warm',
      colors: {
        bgPrimary: '#ff8f00',
        bgSecondary: '#ffa000',
        bgTertiary: '#ffb300',
        textPrimary: '#000000',
        textSecondary: '#212121',
        textMuted: '#424242',
        accentPrimary: '#ff6f00',
        accentSecondary: '#ff8f00',
        borderColor: '#e65100',
        shadowColor: 'rgba(255, 143, 0, 0.3)',
        navBg: 'rgba(255, 143, 0, 0.95)',
        cardBg: 'rgba(255, 160, 0, 0.9)'
      }
    }
  ];

  const handlePaletteSelect = (palette: ColorPalette) => {
    setCustomPalette(palette.colors);
  };

  const handleReset = () => {
    setCustomPalette(null);
  };

  return (
    <div className="color-palette-selector">
      <h3>Paletas de Colores para Neto</h3>
      <p>Colores cálidos y potentes: naranjas, amarillos, granates y negro clásico</p>

      <div className="palette-grid">
        {warmPalettes.map((palette) => (
          <div
            key={palette.id}
            className={`palette-option ${palette.type}`}
            onClick={() => handlePaletteSelect(palette)}
          >
            <div className="palette-preview">
              <div className="color-swatch" style={{ backgroundColor: palette.colors.bgPrimary }}></div>
              <div className="color-swatch" style={{ backgroundColor: palette.colors.bgSecondary }}></div>
              <div className="color-swatch" style={{ backgroundColor: palette.colors.accentPrimary }}></div>
              <div className="color-swatch" style={{ backgroundColor: palette.colors.borderColor }}></div>
            </div>
            <h4>{palette.name}</h4>
            <p className="palette-type">{palette.type === 'warm' ? '🎨 Cálido' : '⚫ Clásico'}</p>
          </div>
        ))}
      </div>

      <div className="palette-actions">
        <button onClick={handleReset} className="reset-button">
          🔄 Restaurar Colores Originales
        </button>
      </div>

      {customColors && (
        <div className="current-palette">
          <h4>Paleta Actual Personalizada</h4>
          <div className="current-colors">
            <div className="color-preview" style={{ backgroundColor: customColors.bgPrimary }}>
              <span>Principal</span>
            </div>
            <div className="color-preview" style={{ backgroundColor: customColors.accentPrimary }}>
              <span>Acento</span>
            </div>
            <div className="color-preview" style={{ backgroundColor: customColors.textPrimary }}>
              <span>Texto</span>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default ColorPaletteSelector;
